package com.thymeandtable.service;
import com.thymeandtable.db.DatabaseConnection; import com.thymeandtable.model.User; import java.sql.*; import java.util.regex.Pattern;
public class AuthService {
 private static final Pattern USERNAME=Pattern.compile("[A-Za-z0-9_]{3,24}");
 public User login(String username,String password)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,username,role,password_hash FROM users WHERE username=?")){p.setString(1,username.trim());try(ResultSet r=p.executeQuery()){if(r.next()&&DatabaseConnection.verifyPassword(password,r.getString("password_hash")))return new User(r.getInt("id"),r.getString("username"),r.getString("role"));return null;}}}
 public String register(String username,String password,String role)throws SQLException{username=username==null?"":username.trim();if(!USERNAME.matcher(username).matches())return "Username must be 3–24 letters, numbers or underscores.";if(password==null||password.length()<8)return "Password must contain at least 8 characters.";if(!"USER".equals(role)&&!"INFLUENCER".equals(role))return "Invalid role.";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(username,password_hash,role) VALUES(?,?,?)")){p.setString(1,username);p.setString(2,DatabaseConnection.hashPassword(password));p.setString(3,role);p.executeUpdate();if("INFLUENCER".equals(role)){try(PreparedStatement q=c.prepareStatement("INSERT INTO influencer_profiles(user_id,display_name,bio,speciality) VALUES((SELECT id FROM users WHERE username=?),?,?,?)")){q.setString(1,username);q.setString(2,username);q.setString(3,"New food creator");q.setString(4,"Home cooking");q.executeUpdate();}}return "";}catch(SQLException e){if(e.getMessage()!=null&&e.getMessage().toLowerCase().contains("unique"))return "That username is already taken.";throw e;}}
}
